-- SERIES 3
SET NAMES utf8mb4;
DROP PROCEDURE IF EXISTS nova_de_v3_s003;
DELIMITER $$
CREATE PROCEDURE nova_de_v3_s003()
BEGIN
  DECLARE v_count INT DEFAULT 0;
  DECLARE v_course BIGINT UNSIGNED; DECLARE v_level BIGINT UNSIGNED; DECLARE v_module BIGINT UNSIGNED; DECLARE v_chapter BIGINT UNSIGNED;
  DECLARE v_c_raha BIGINT UNSIGNED; DECLARE v_c_jonas BIGINT UNSIGNED;
  DECLARE v_l_1 BIGINT UNSIGNED; DECLARE v_l_2 BIGINT UNSIGNED; DECLARE v_l_3 BIGINT UNSIGNED; DECLARE v_l_4 BIGINT UNSIGNED;
  DECLARE v_u_1 BIGINT UNSIGNED; DECLARE v_u_2 BIGINT UNSIGNED; DECLARE v_u_3 BIGINT UNSIGNED; DECLARE v_u_4 BIGINT UNSIGNED; DECLARE v_u_5 BIGINT UNSIGNED; DECLARE v_u_6 BIGINT UNSIGNED; DECLARE v_u_7 BIGINT UNSIGNED; DECLARE v_u_8 BIGINT UNSIGNED; DECLARE v_u_9 BIGINT UNSIGNED;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  SELECT COUNT(*),MIN(id) INTO v_count,v_course FROM courses WHERE learning_language='de' AND base_language='fa'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='de-fa course identity missing or not unique'; END IF;
  SELECT COUNT(*),MIN(id) INTO v_count,v_level FROM levels WHERE course_id=v_course AND cefr_level='A1'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='de-fa A1 missing or not unique'; END IF;
  SELECT COUNT(*),MIN(id) INTO v_count,v_module FROM modules WHERE level_id=v_level AND sort_order=1; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='de-fa module 1 missing or not unique'; END IF;
  SELECT COUNT(*),MIN(id) INTO v_count,v_c_raha FROM characters WHERE course_id=v_course AND name='Raha' AND gender='female'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Raha identity missing or not unique'; END IF;
  SELECT COUNT(*),MIN(id) INTO v_count,v_c_jonas FROM characters WHERE course_id=v_course AND name='Jonas' AND gender='male'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Jonas identity missing or not unique'; END IF;
  SELECT COUNT(*),MIN(id) INTO v_count,v_chapter FROM chapters WHERE module_id=v_module AND sort_order=3;
  IF v_count=0 THEN
    SELECT id INTO v_u_1 FROM learning_units WHERE course_id=v_course AND unit_key='de:a1:welche-sprachen-sprichst-du'; SELECT id INTO v_u_2 FROM learning_units WHERE course_id=v_course AND unit_key='de:a1:ich-spreche'; SELECT id INTO v_u_3 FROM learning_units WHERE course_id=v_course AND unit_key='de:a1:sprichst-du-deutsch'; SELECT id INTO v_u_4 FROM learning_units WHERE course_id=v_course AND unit_key='de:a1:ein-bisschen'; SELECT id INTO v_u_5 FROM learning_units WHERE course_id=v_course AND unit_key='de:a1:grammar:sprechen-ich-du'; SELECT id INTO v_u_6 FROM learning_units WHERE course_id=v_course AND unit_key='de:a1:persisch:language'; SELECT id INTO v_u_7 FROM learning_units WHERE course_id=v_course AND unit_key='de:a1:deutsch:language'; SELECT id INTO v_u_8 FROM learning_units WHERE course_id=v_course AND unit_key='de:a1:pron:sprache-stress'; SELECT id INTO v_u_9 FROM learning_units WHERE course_id=v_course AND unit_key='de:a1:can-do:languages';
      ON DUPLICATE KEY UPDATE status=status;





    UPDATE review_obligations SET status='fulfilled',fulfilled_chapter_id=v_chapter,metadata=JSON_SET(COALESCE(metadata,JSON_OBJECT()),'$.evidenceSeries',3,'$.evidenceType','retrieval_transfer','$.evidenceFile','review_evidence_v3.json') WHERE course_id=v_course AND due_series=3 AND status='due';
    UPDATE curriculum_outcomes SET status='covered',evidence=JSON_ARRAY(JSON_OBJECT('series',3,'lesson',4,'type','mastery_transfer')) WHERE course_id=v_course AND cefr_level='A1' AND outcome_key IN ('can_do:state_languages','can_do:ask_languages','grammar:sprechen_ich_du','grammar:yes_no_question_language','reading:identity_languages','listening:identity_languages','pron:basic_word_stress');
  END IF;
  COMMIT;
END$$
DELIMITER ;
CALL nova_de_v3_s003();
DROP PROCEDURE nova_de_v3_s003;
